@router.patch("/gateway/rate-limits/{policy_pk}")
async def update_rate_limit_policy(
    policy_pk: str,
    payload: RateLimitUpdatePayload,
    current_user: User = Depends(get_current_user)
):
    try:
        policy = RateLimitPolicy.get(policy_pk)
    except NotFoundError:
        raise HTTPException(status_code=404, detail="Rate limit policy not found")

    if policy.org_id != current_user.org_id and not current_user.is_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to modify rate limits of other organizations")

    policy.requests_per_minute = payload.requests_per_minute
    policy.burst_allowance = payload.burst_allowance
    policy.save()

    return {"status": "policy_updated", "policy_pk": policy.pk, "rpm": policy.requests_per_minute}
